/// 一件有期限、要處理的事（客服案件或一組內容檢舉）；不含使用者文字與 email
class TimedCase {
  const TimedCase({
    required this.id,
    required this.type,
    required this.kind,
    required this.state,
    required this.dueAt,
    required this.bucket,
    required this.rank,
    this.version,
    required this.lastActivityAt,
    required this.suspicious,
    this.reportCount,
    this.hiddenParts,
    this.spotId,
    this.pendingAction,
  });

  factory TimedCase.fromJson(Map<String, Object?> json) => TimedCase(
    id: json['id'] as String,
    type: json['type'] as String,
    kind: json['kind'] as String,
    state: json['state'] as String,
    dueAt: json['due_at'] as String,
    bucket: json['bucket'] as String,
    rank: (json['rank'] as num).toInt(),
    version: json['version'] == null ? null : json['version'] as String,
    lastActivityAt: json['last_activity_at'] as String,
    suspicious: json['suspicious'] as bool,
    reportCount: json['report_count'] == null
        ? null
        : (json['report_count'] as num).toInt(),
    hiddenParts: json['hidden_parts'] == null
        ? null
        : [for (final e in json['hidden_parts'] as List) e as String],
    spotId: json['spot_id'] == null ? null : json['spot_id'] as String,
    pendingAction: json['pending_action'],
  );

  /// 客服＝案件 id（admin_v1.support_request 的 p_id）；檢舉＝組內最早一則的 id（admin_v1.content_report 的 p_id）
  final String id;

  final String type;

  /// 客服＝案件類型（general、data_issue、complaint、privacy、account_deletion）；檢舉＝target（rider_name、spot_name、text、impersonation、other）
  final String kind;

  /// 客服：send_failed 最後一則回覆寄送失敗且不再自動重試，或最新的排程動作失敗；system 不能回覆（刪除帳號、個資請求未確認本人），由系統處理；awaiting_admin 等客服回覆；awaiting_user 等對方。檢舉：spot_deleted 點位已被刪除；held 被檢舉的部分遮蔽中；open 沒有遮蔽（other，或命中不立即隱藏的規則）；send_failed 最新的排程動作失敗。兩者：scheduled 有排程動作在倒數（bucket 不變）
  final String state;

  /// 期限：5 個工作天結束（台灣時間，依 public.holidays；補班日算工作日）。客服從送出或重新開啟起算，檢舉從組內最早一則起算
  final String dueAt;

  /// waiting＝awaiting_user、system；其餘依期限（today＝今天結束前到期，台灣時間）
  final String bucket;

  /// 排序第一鍵：send_failed 0、overdue 1、today／later 2、waiting 3
  final int rank;

  /// 之後的寫入帶回比對（不符回 409）。客服＝案件狀態與最後一則往來紀錄的時間；檢舉＝點位 updated_at（點位已不存在時 null）
  final String? version;

  final String lastActivityAt;

  /// 客服：寄件人未通過驗證的信；檢舉一律 false
  final bool suspicious;

  /// 檢舉：組內處理中的檢舉數；客服 null
  final int? reportCount;

  /// 檢舉：目前遮蔽中的部分（空陣列＝沒有遮蔽，不要顯示「放回 App」）；客服 null
  final List<String>? hiddenParts;

  /// 檢舉的點位；客服 null
  final String? spotId;

  /// 這個案件最新的排程動作還需要注意時（倒數中、失敗或 stale）；否則 null
  final Object? pendingAction;

  Map<String, Object?> toJson() => {
    'id': id,
    'type': type,
    'kind': kind,
    'state': state,
    'due_at': dueAt,
    'bucket': bucket,
    'rank': rank,
    'version': version,
    'last_activity_at': lastActivityAt,
    'suspicious': suspicious,
    'report_count': reportCount,
    'hidden_parts': hiddenParts,
    'spot_id': spotId,
    'pending_action': pendingAction,
  };

  @override
  bool operator ==(Object other) =>
      other is TimedCase &&
      other.id == id &&
      other.type == type &&
      other.kind == kind &&
      other.state == state &&
      other.dueAt == dueAt &&
      other.bucket == bucket &&
      other.rank == rank &&
      other.version == version &&
      other.lastActivityAt == lastActivityAt &&
      other.suspicious == suspicious &&
      other.reportCount == reportCount &&
      _equal(other.hiddenParts, hiddenParts) &&
      other.spotId == spotId &&
      _equal(other.pendingAction, pendingAction);

  @override
  int get hashCode => Object.hashAll([
    id,
    type,
    kind,
    state,
    dueAt,
    bucket,
    rank,
    version,
    lastActivityAt,
    suspicious,
    reportCount,
    _hash(hiddenParts),
    spotId,
    _hash(pendingAction),
  ]);
}

