class CaseAction {
  const CaseAction({
    required this.id,
    required this.caseType,
    required this.caseId,
    required this.action,
    required this.status,
    required this.runAt,
    required this.irreversible,
    required this.attempts,
    this.error,
    required this.actor,
    this.expectedVersion,
    required this.payload,
    required this.createdAt,
    this.startedAt,
    this.finishedAt,
    this.messageId,
    this.deliveryStatus,
    this.sendError,
    required this.addressEditable,
  });

  factory CaseAction.fromJson(Map<String, Object?> json) => CaseAction(
    id: json['id'] as String,
    caseType: json['case_type'] as String,
    caseId: json['case_id'] as String,
    action: json['action'] as String,
    status: json['status'] as String,
    runAt: json['run_at'] as String,
    irreversible: json['irreversible'] as bool,
    attempts: (json['attempts'] as num).toInt(),
    error: json['error'] == null ? null : json['error'] as String,
    actor: json['actor'] as String,
    expectedVersion: json['expected_version'] == null
        ? null
        : json['expected_version'] as String,
    payload: Map<String, Object?>.from(json['payload'] as Map),
    createdAt: json['created_at'] as String,
    startedAt: json['started_at'] == null ? null : json['started_at'] as String,
    finishedAt: json['finished_at'] == null
        ? null
        : json['finished_at'] as String,
    messageId: json['message_id'] == null ? null : json['message_id'] as String,
    deliveryStatus: json['delivery_status'] == null
        ? null
        : json['delivery_status'] as String,
    sendError: json['send_error'] == null ? null : json['send_error'] as String,
    addressEditable: json['address_editable'] as bool,
  );

  final String id;

  final String caseType;

  final String caseId;

  final String action;

  /// done 只在回覆的信寄不出去時列出（可再寄一次）
  final String status;

  final String runAt;

  final bool irreversible;

  final int attempts;

  /// 穩定錯誤碼或 SQLSTATE
  final String? error;

  final String actor;

  final String? expectedVersion;

  /// 排程時帶的內容，用來還原草稿；done 是空物件
  final Map<String, Object?> payload;

  final String createdAt;

  final String? startedAt;

  final String? finishedAt;

  final String? messageId;

  /// 回覆的寄送狀態：queued、sending、sent、failed；沒有回覆時 null
  final String? deliveryStatus;

  final String? sendError;

  /// 目前一律 false：後端沒有改地址的 API
  final bool addressEditable;

  Map<String, Object?> toJson() => {
    'id': id,
    'case_type': caseType,
    'case_id': caseId,
    'action': action,
    'status': status,
    'run_at': runAt,
    'irreversible': irreversible,
    'attempts': attempts,
    'error': error,
    'actor': actor,
    'expected_version': expectedVersion,
    'payload': payload,
    'created_at': createdAt,
    'started_at': startedAt,
    'finished_at': finishedAt,
    'message_id': messageId,
    'delivery_status': deliveryStatus,
    'send_error': sendError,
    'address_editable': addressEditable,
  };

  @override
  bool operator ==(Object other) =>
      other is CaseAction &&
      other.id == id &&
      other.caseType == caseType &&
      other.caseId == caseId &&
      other.action == action &&
      other.status == status &&
      other.runAt == runAt &&
      other.irreversible == irreversible &&
      other.attempts == attempts &&
      other.error == error &&
      other.actor == actor &&
      other.expectedVersion == expectedVersion &&
      _equal(other.payload, payload) &&
      other.createdAt == createdAt &&
      other.startedAt == startedAt &&
      other.finishedAt == finishedAt &&
      other.messageId == messageId &&
      other.deliveryStatus == deliveryStatus &&
      other.sendError == sendError &&
      other.addressEditable == addressEditable;

  @override
  int get hashCode => Object.hashAll([
    id,
    caseType,
    caseId,
    action,
    status,
    runAt,
    irreversible,
    attempts,
    error,
    actor,
    expectedVersion,
    _hash(payload),
    createdAt,
    startedAt,
    finishedAt,
    messageId,
    deliveryStatus,
    sendError,
    addressEditable,
  ]);
}

class TimedCasePage {
  const TimedCasePage({required this.items, this.nextCursor});

  factory TimedCasePage.fromJson(Map<String, Object?> json) => TimedCasePage(
    items: [
      for (final e in json['items'] as List)
        TimedCase.fromJson(e as Map<String, Object?>),
    ],
    nextCursor: json['next_cursor'],
  );

  final List<TimedCase> items;

  /// 還有下一頁時的游標；沒有時 null
  final Object? nextCursor;

  Map<String, Object?> toJson() => {
    'items': [for (final e in items) e.toJson()],
    'next_cursor': nextCursor,
  };

  @override
  bool operator ==(Object other) =>
      other is TimedCasePage &&
      _equal(other.items, items) &&
      _equal(other.nextCursor, nextCursor);

  @override
  int get hashCode => Object.hashAll([_hash(items), _hash(nextCursor)]);
}

/// all＝overdue＋today＋later（waiting 另計）；send_failed 也算在 all 與它的 bucket 裡。取不到時用戶端顯示未知，不要顯示 0
class TimedCaseCounts {
  const TimedCaseCounts({
    required this.all,
    required this.overdue,
    required this.today,
    required this.later,
    required this.waiting,
    required this.sendFailed,
    required this.byKind,
    required this.asOf,
  });

  factory TimedCaseCounts.fromJson(Map<String, Object?> json) =>
      TimedCaseCounts(
        all: (json['all'] as num).toInt(),
        overdue: (json['overdue'] as num).toInt(),
        today: (json['today'] as num).toInt(),
        later: (json['later'] as num).toInt(),
        waiting: (json['waiting'] as num).toInt(),
        sendFailed: (json['send_failed'] as num).toInt(),
        byKind: Map<String, Object?>.from(json['by_kind'] as Map),
        asOf: json['as_of'] as String,
      );

  final int all;

  final int overdue;

  final int today;

  final int later;

  final int waiting;

  final int sendFailed;

  /// 只算 all 的列；鍵是 support、report、`support:<類型>`、`report:<target>`，0 筆的鍵不出現
  final Map<String, Object?> byKind;

  final String asOf;

  Map<String, Object?> toJson() => {
    'all': all,
    'overdue': overdue,
    'today': today,
    'later': later,
    'waiting': waiting,
    'send_failed': sendFailed,
    'by_kind': byKind,
    'as_of': asOf,
  };

  @override
  bool operator ==(Object other) =>
      other is TimedCaseCounts &&
      other.all == all &&
      other.overdue == overdue &&
      other.today == today &&
      other.later == later &&
      other.waiting == waiting &&
      other.sendFailed == sendFailed &&
      _equal(other.byKind, byKind) &&
      other.asOf == asOf;

  @override
  int get hashCode => Object.hashAll([
    all,
    overdue,
    today,
    later,
    waiting,
    sendFailed,
    _hash(byKind),
    asOf,
  ]);
}

bool _equal(Object? a, Object? b) {
  if (a is List && b is List) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!_equal(a[i], b[i])) return false;
    }
    return true;
  }
  if (a is Map && b is Map) {
    if (a.length != b.length) return false;
    for (final key in a.keys) {
      if (!b.containsKey(key) || !_equal(a[key], b[key])) return false;
    }
    return true;
  }
  return a == b;
}

int _hash(Object? value) => switch (value) {
  List() => Object.hashAll(value.map(_hash)),
  Map() => Object.hashAllUnordered(
    value.entries.map((e) => Object.hash(e.key, _hash(e.value))),
  ),
  _ => value.hashCode,
};
